alter table public.customer_appointment_requests add column preferred_at timestamptz;
create index portal_requests_company_preferred_at_idx on public.customer_appointment_requests(company_id,preferred_at)where preferred_at is not null;
create function private.portal_available_slots(p_service uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare c public.customers;co public.companies;s public.services;begin c:=private.portal_customer();select*into co from public.companies where id=c.company_id;select*into s from public.services where id=p_service and company_id=c.company_id and is_active;if not found then raise exception'Serviço inválido';end if;return coalesce((select jsonb_agg(jsonb_build_object('starts_at',z.slot,'label',to_char(z.slot at time zone'America/Sao_Paulo','DD/MM/YYYY HH24:MI'))order by z.slot)from(select slot from generate_series(current_date+1,current_date+30,interval'1 day')d cross join lateral generate_series((d::date+co.opening_time)at time zone'America/Sao_Paulo',((d::date+co.closing_time)at time zone'America/Sao_Paulo')-make_interval(mins=>s.estimated_duration_minutes),interval'30 minutes')slot where not exists(select 1 from public.blocked_times b where b.company_id=c.company_id and b.employee_id is null and slot<b.end_at and slot+make_interval(mins=>s.estimated_duration_minutes)>b.start_at)and(select count(*)from public.appointments a where a.company_id=c.company_id and a.scheduled_at=slot and a.status not in('cancelado','faltou'))<co.capacity_per_slot order by slot limit 120)z),'[]');end$$;
drop function public.request_customer_appointment(uuid,uuid,date,text,text);drop function private.portal_request(uuid,uuid,date,text,text);
create function private.portal_request(p_pet uuid,p_service uuid,p_slot timestamptz,p_notes text)returns uuid language plpgsql security definer set search_path=''as $$declare c public.customers;co public.companies;s public.services;r uuid;begin c:=private.portal_customer();select*into co from public.companies where id=c.company_id;select*into s from public.services where id=p_service and company_id=c.company_id and is_active;if p_slot<now()or not found or not exists(select 1 from public.pets where id=p_pet and customer_id=c.id)or(p_slot at time zone'America/Sao_Paulo')::time<co.opening_time or(p_slot at time zone'America/Sao_Paulo')::time+make_interval(mins=>s.estimated_duration_minutes)>co.closing_time or exists(select 1 from public.blocked_times b where b.company_id=c.company_id and b.employee_id is null and p_slot<b.end_at and p_slot+make_interval(mins=>s.estimated_duration_minutes)>b.start_at)or(select count(*)from public.appointments a where a.company_id=c.company_id and a.scheduled_at=p_slot and a.status not in('cancelado','faltou'))>=co.capacity_per_slot then raise exception'Horário indisponível';end if;insert into public.customer_appointment_requests(company_id,customer_id,auth_user_id,pet_id,service_id,preferred_date,preferred_period,preferred_at,notes)values(c.company_id,c.id,(select auth.uid()),p_pet,p_service,(p_slot at time zone'America/Sao_Paulo')::date,case when(p_slot at time zone'America/Sao_Paulo')::time<'12:00'then'manha'else'tarde'end,p_slot,p_notes)returning id into r;return r;end$$;
create function public.get_portal_availability(p_service uuid)returns jsonb language sql security invoker set search_path=''as $$select private.portal_available_slots(p_service)$$;create function public.request_customer_appointment(p_pet uuid,p_service uuid,p_slot timestamptz,p_notes text default null)returns uuid language sql security invoker set search_path=''as $$select private.portal_request(p_pet,p_service,p_slot,p_notes)$$;
revoke all on function private.portal_available_slots(uuid),private.portal_request(uuid,uuid,timestamptz,text)from public,anon;grant execute on function private.portal_available_slots(uuid),private.portal_request(uuid,uuid,timestamptz,text)to authenticated;revoke all on function public.get_portal_availability(uuid),public.request_customer_appointment(uuid,uuid,timestamptz,text)from public,anon;grant execute on function public.get_portal_availability(uuid),public.request_customer_appointment(uuid,uuid,timestamptz,text)to authenticated;
